  /** World → screen projection used by HUD for nameplates + damage numbers. */
  worldToScreen(world: THREE.Vector3, out: THREE.Vector2): boolean {
    if (!this.player || !this.camera) return false;
    const v = world.clone().project(this.camera.camera);
    if (v.z < -1 || v.z > 1) return false;
    const rect = this.renderer.domElement.getBoundingClientRect();
    out.x = ((v.x + 1) / 2) * rect.width;
    out.y = ((-v.y + 1) / 2) * rect.height;
    return true;
  }

  get playerPos(): THREE.Vector3 { return this.player?.position ?? new THREE.Vector3(); }
  get zoneName(): string { return this.currentZoneName; }
  get renderScale(): number { return this.renderResolution.scale; }
  get frameMs(): number { return this.frameMilliseconds; }
  get performanceSample() { return this.diagnostics.latest; }
  get cityDistrictName(): string | null {
    if (!this.currentZone?.cityDistricts?.length || !this.player || this.houseInteriors?.isActive) return null;
    const position = this.player.position;
    if (this.currentZone.craterCity) {
      const level = craterLevel(this.currentZone.craterCity, position.y);
      const distance = (d: { x: number; y?: number; z: number }) => Math.hypot(d.x-position.x,d.z-position.z,2*((d.y??0)-position.y));
      const nearestHeight = Math.min(...this.currentZone.cityDistricts.map(d => Math.abs((d.y??0)-position.y)));
      const districts = this.currentZone.cityDistricts.filter(d => Math.abs((d.y??0)-position.y) <= nearestHeight+30);
      const district = districts.reduce((a,b) => distance(a) < distance(b) ? a : b);
      return `${district.name} · ${level.id} level · ${Math.round(position.y)} m`;
    }
    return this.currentZone.cityDistricts.reduce((nearest, district) =>
      Math.hypot(district.x-position.x,district.z-position.z)<Math.hypot(nearest.x-position.x,nearest.z-position.z)?district:nearest
    ).name;
  }
  get cityMapGeometry() {
    return this.currentZone?.cityLayoutVersion ? this.mapZoneDefinition : null;
  }
  get mapZoneDefinition(): ZoneDefinition | null {
    const source = this.currentZone;
    if (!source) return null;
    const editor = this.worldEditor;
    const revision = editor?.mapRevision ?? 0;
    if (this.cachedMapZone?.source !== source || this.cachedMapZone.editor !== editor || this.cachedMapZone.revision !== revision) {
      this.cachedMapZone = { source, editor, revision, zone: resolveMapZone(source, editor ? editor.currentDocument : this.publishedWorldEdit) };
    }
    return this.cachedMapZone.zone;
  }
  get zoneDefinition(): ZoneDefinition | null { return this.currentZone; }
  get campaignActivity(): { zone: CampaignZoneStatus; focus: CampaignActivity | null; progress: number } | null {
    if (!this.campaignZoneStatus) return null;
    const candidates = this.campaignActivities(useGameStore.getState());
    // Keep the nearby point visible, including its blocker; otherwise guide toward the next available activity.
    const focus = candidates.find((entry) => entry.distance <= entry.objective.captureRadius) ??
      candidates.find((entry) => !entry.blocker || entry.blocker.startsWith('Defeat')) ?? candidates[0] ?? null;
    const progress = focus && this.objectiveCapture?.objectiveId === focus.objective.id
      ? campaignActivityProgress(this.objectiveCapture.startedAtMs, performance.now(), focus.holdMs) : 0;
    return { zone: this.campaignZoneStatus, focus, progress };
  }
  teleportPlayerTo(
    point: { x: number; y?: number; z: number },
    rotationY = this.player?.rotationY ?? this.character.rotationY,
  ): { x: number; y: number; z: number } {
    if (!this.player) throw new Error('Player is not ready.');
    if (!Number.isFinite(point.x) || !Number.isFinite(point.z)) {
      throw new Error('Teleport target must include finite x and z coordinates.');
    }

    const yHint = Number.isFinite(point.y) ? point.y : undefined;
    const nextPosition = {
      x: point.x,
      y: this.groundHeightAt(point.x, point.z, yHint),
      z: point.z,
    };
    this.player.teleportTo(nextPosition, rotationY);
    this.character.position = nextPosition;
    this.character.rotationY = rotationY;
    this.zoneTransitionArmed = false;
    this.zoneTransitionGraceUntilMs = performance.now() + ZONE_TRANSITION_GRACE_MS;

    const store = useGameStore.getState();
    store.updateCharacter({ position: nextPosition, rotationY });
    store.setPlayerDead(false);
    for (const enemy of this.enemies) {
      enemy.aggroed = false;
      enemy.attackCooldown = 0;
    }
    void services.characters.save(this.character.id, { position: nextPosition, rotationY });
    void services.world.updatePosition(this.character.zoneId, {
      userId: store.user?.id ?? 'unknown',
      characterId: this.character.id,
      name: this.character.name,
      position: nextPosition,
      rotationY,
    }).catch(() => {});
    return nextPosition;
  }

  get craftingStationMarkers(): Array<{
    id: string;
    label: string;
    kind: CraftingStationSpawn['kind'];
    position: { x: number; y: number; z: number };
  }> {
    return this.craftingStations.map((station) => ({
      id: station.id,
      label: station.label,
      kind: station.kind,
      position: {
        x: station.x,
        y: this.groundHeightAt(station.x, station.z, station.y),
        z: station.z,
      },
    }));
  }
  get resourceNodeMarkers(): Array<{
    id: string;
    label: string;
    kind: ResourceNodeSpawn['kind'];
    available: boolean;
    position: { x: number; y: number; z: number };
  }> {
    const zoneId = this.currentZone?.id;
    const craftingState = useGameStore.getState().craftingState;
    return this.resourceNodes.map((node) => ({
      id: node.id,
      label: node.label,
      kind: node.kind,
      available: Boolean(zoneId && isResourceNodeAvailable(craftingState, zoneId, node.id)),
      position: {
        x: node.x,
        y: this.groundHeightAt(node.x, node.z, node.y),
        z: node.z,
      },
    }));
  }

  /** Proxy for the touch joystick — called by TouchControls each pointer-move. */
  setTouchAxis(x: number, z: number) {
    this.input?.setTouchAxis(x, z);
  }

  /** Proxy for the touch jump button. */
